// NORMALIZAR
// Cada ATS devuelve una forma distinta. Toda esa diferencia vive AQUI
// y solo aqui. Agregar un ATS nuevo = agregar una entrada al mapa.

const hoy = new Date().toISOString().slice(0, 10);

// Emparejamos cada respuesta HTTP con la empresa que la origino,
// usando el mismo indice: n8n conserva el orden de los items.
const empresas = $('Leer empresas').all();
const respuestas = $input.all();

const mapeo = {
  greenhouse: (v) => ({
    id_externo: String(v.id),
    titulo: v.title,
    ubicacion: v.location?.name ?? 'sin especificar',
    url: v.absolute_url
  }),
  lever: (v) => ({
    id_externo: v.id,
    titulo: v.text,
    ubicacion: v.categories?.location ?? 'sin especificar',
    url: v.hostedUrl
  })
};

const salida = [];

respuestas.forEach((res, i) => {
  const { empresa, fuente } = empresas[i].json;

  // Greenhouse devuelve { jobs: [...] }, Lever devuelve el array pelado.
  const vacantes = res.json?.jobs ?? (Array.isArray(res.json) ? res.json : []);
  if (!mapeo[fuente]) return;

  vacantes.forEach((v) => {
    const base = mapeo[fuente](v);

    salida.push({
      json: {
        ...base,
        empresa,
        fuente,
        // Clave 1: identidad tecnica. Compuesta porque dos empresas
        // distintas pueden usar el mismo id numerico.
        clave: `${fuente}:${empresa}:${base.id_externo}`,
        // Clave 2: huella de contenido. Sobrevive a la republicacion
        // con id nuevo, que es el churn del que nos queremos proteger.
        huella: `${empresa}:${base.titulo.toLowerCase().replace(/[^a-z0-9]/g, '')}`,
        descubierta: hoy,
        estado: 'nueva'
      }
    });
  });
});

return salida;

// DEDUPLICAR
// Una vacante es nueva solo si NINGUNA de sus dos claves ya existe.
// Si la clave no esta en el registro, es de las ultimas 24h:
// la frescura sale gratis de la deduplicacion, sin guardar historial.

const registro = $input.all();

// Set en vez de array: la busqueda pasa de O(n) a O(1).
// Con 3000 filas x 900 vacantes por corrida, la diferencia se nota.
const clavesVistas = new Set(registro.map((r) => r.json.clave));
const huellasVistas = new Set(registro.map((r) => r.json.huella));

const nuevas = $('Normalizar').all().filter((v) => {
  return !clavesVistas.has(v.json.clave) && !huellasVistas.has(v.json.huella);
});

console.log(`Nuevas: ${nuevas.length} de ${$('Normalizar').all().length} revisadas`);

return nuevas;
